"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["78105"],{11314(e,t,r){r.r(t),r.d(t,{metadata:()=>n,default:()=>l,frontMatter:()=>p,contentTitle:()=>c,toc:()=>h,assets:()=>d});var n=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-product-getowner","title":"Get product owner","description":"Resolves a product ID to the participant code of the payer that owns it.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-product-getowner.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-product-getowner","permalink":"/docs/pr-15/docs/nhcx/v1/api/registry/endpoints/registry-product-getowner","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Get product owner","sidebar_label":"Get product owner","sidebar_class_name":"api-method api-method--post","description":"Resolves a product ID to the participant code of the payer that owns it.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Submit the de-link payer product","permalink":"/docs/pr-15/docs/nhcx/v1/api/registry/endpoints/registry-product-delink"},"next":{"title":"Get product ID and name","permalink":"/docs/pr-15/docs/nhcx/v1/api/registry/endpoints/registry-participant-getproductidname"}}'),i=r(62540),a=r(43023),o=r(75064),s=JSON.parse('{"id":"registry_product_getowner","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/product/getowner","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Get product owner","title":"Get product owner","description":"Resolves a product ID to the participant code of the payer that owns it.\\n\\n### Business purpose\\n\\nGiven only a product identifier, an integrator often needs to know which payer stands behind it. This Retrieving API call takes a ProductOwnerRequest with productid and returns ParticipantCreateResponse, whose participant_code is the owning participant\'s identifier on the HCX instance. That makes it a useful bridge between a product seen on a policy document or in a policy lookup and the participant code that must go into routing. Note that the OpenAPI description reads \\"This API is to generate the product ID and product Name\\", which does not match the response schema; the source does not resolve this conflict.\\n\\n### When to use\\n\\nUse it when you hold a product ID but not the payer participant code, for example while normalising a policy lookup or verifying a newly linked product. It is a synchronous helper in the member layer, used before InsurancePlan retrieval, coverage eligibility or preauthorisation rather than during them. Payers use it after /product/link or /product/delink to confirm the registry state.\\n\\n### Preconditions\\n\\n- A valid Bearer token from the client-credentials call (POST /get/session, form-urlencoded client_ID, client_secret, grant_type=client_credentials); tokens last 1200 seconds, so refresh before expiry.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth: Bearer <token> (the participant service uses bearer_auth, not Authorisation).\\n- Base path for the participant service: https://apisbx.ABDM.gov.in/pmjay/sbxhcx/participanthcxservice (sandbox) or https://apisprod.NHA.gov.in/pmjay/hcx/participanthcxservice (production).\\n- This is a synchronous plain-JSON registry call: no JWE envelope, no x-hcx-* protocol headers and no correlation ID are involved.\\n- Body is ProductOwnerRequest with a single optional string, productid; supply it, since the lookup has no other input.\\n- The product must have been registered by its payer through /product/link.\\n\\n### Postconditions\\n\\nReturns HTTP 200 with ParticipantCreateResponse containing the optional participant_code of the owning participant. No callback follows and no state changes. Failures return 400, 404 or 500 with the ErrorResponse envelope. The returned code identifies the payer (the payerid used in policy links); remember that for NHCX routing the receiver code should come from the processingID given by the get-policies response, which may be a TPA rather than this owner.\\n\\n### Common mistakes\\n\\n- Using the returned participant_code directly as x-hcx-recipient_code when the payer is processed by a TPA; NHA\'s common mistake 7 says the receiver code is the processingID from get/Policies.\\n- Expecting product name or other product details in the response; only participant_code is returned.\\n- Sending an empty body; productid is optional in the schema but the lookup needs it.\\n- Confusing this endpoint with /participant/getProductIdName, which carries the same description but a different request shape.\\n- Omitting the Accept header or the Bearer prefix.\\n\\n### Best practices\\n\\n- Treat the result as the product owner (payerid), then resolve the effective receiver through the policy lookup.\\n- Cache owner lookups by productid; ownership changes rarely and only through /product/link and /product/delink.\\n- Handle a missing participant_code gracefully; every field in the response is optional.\\n- Refresh the Bearer token proactively and retry once on 401.\\n\\n### Related scenario\\n\\nA hospital receives a scanned policy card that shows only a product ID, and the patient\'s ABHA-based policy lookup returned more than one payer. The HMIS calls /product/getowner with the product ID and gets back the participant code of the insurer that owns it, which lets the desk pick the right entry from the /participant/get/policies result. With the matched policy in hand the system reads the processingID as the receiver code, requests the plan through /v1/insuranceplan/request and goes on to submit the preauthorisation.\\n\\n### Specification\\n\\nChapter [Participants and policies](/docs/nhcx/v1/registries) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"productid","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"productid":"PRD-FLOATER-01"},"responses":[{"status":"200","description":"Returns HTTP 200 with ParticipantCreateResponse containing the optional participant_code of the owning participant.","example":{"participant_code":"100234@sbx"}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"productid\\": \\"PRD-FLOATER-01\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"productid\\": \\"PRD-FLOATER-01\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"productid\\": \\"PRD-FLOATER-01\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/product/getowner\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"productid\\": \\"PRD-FLOATER-01\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let p={title:"Get product owner",sidebar_label:"Get product owner",sidebar_class_name:"api-method api-method--post",description:"Resolves a product ID to the participant code of the payer that owns it.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},c,d={},h=[];function u(e){return(0,i.jsx)(o.A,{operation:s})}function l(e={}){let{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(u,{...e})}):u(e)}}}]);